== EntryControlCC.ts
10:    10	import type { ZWaveNode } from "../Node.js";
11:    11	
12:    12	export interface EntryControlHandlerStore {
13:    13		recentSequenceNumbers: number[];
14:    14	}
15:    15	
16:    16	export function getDefaultEntryControlHandlerStore(): EntryControlHandlerStore {
17:    17		return {
18:    18			recentSequenceNumbers: [],
19:    19		};
20:    20	}
21:    21	
22:    22	export function handleEntryControlNotification(
23:    23		ctx: PersistValuesContext & LogNode,
24:    24		node: ZWaveNode,
25:    25		command: EntryControlCCNotification,
26:    26		store: EntryControlHandlerStore,
27:    27	): void {
28:    28		if (!node.deviceConfig?.compat?.disableStrictEntryControlDataValidation) {
29:    29			if (store.recentSequenceNumbers.includes(command.sequenceNumber)) {
30:    30				ctx.logNode(
31:    31					node.id,
32:    32					`Received duplicate Entry Control Notification (sequence number ${command.sequenceNumber}), ignoring...`,
33:    33					"warn",
34:    34				);
35:    35				return;
36:    36			}
37:    37	
38:    38			// Keep track of the last 5 sequence numbers
39:    39			store.recentSequenceNumbers.unshift(command.sequenceNumber);
40:    40			if (store.recentSequenceNumbers.length > 5) {
41:    41				store.recentSequenceNumbers.pop();
42:    42			}
43:    43		}
44:    44	
45:    45		// Notify listeners
46:    46		const endpoint = node.getEndpoint(command.endpointIndex) ?? node;
47:    47	
48:    48		node.emit("notification", endpoint, CommandClasses["Entry Control"], {
49:    49			...pick(command, ["eventType", "dataType", "eventData"]),
50:    50			eventTypeLabel: entryControlEventTypeLabels[command.eventType],
51:    51			dataTypeLabel: getEnumMemberName(
52:    52				EntryControlDataTypes,
53:    53				command.dataType,
54:    54			),
55:    55		});
56:    56	}
