	public readonly sequenceNumber: number;
	public readonly dataType: EntryControlDataTypes;
	public readonly eventType: EntryControlEventTypes;
	public readonly eventData?: BytesView | string;

	public serialize(ctx: CCEncodingContext): Promise<Bytes> {
		let data =
			typeof this.eventData === "string"
				? Bytes.from(this.eventData, "ascii")
				: Bytes.from(this.eventData ?? []);
		// RAW and ASCII: 1 to 32 bytes; MD5: exactly 16 bytes
		if (
			data.length > 32
			|| (this.dataType === EntryControlDataTypes.MD5
				&& data.length !== 16)
		) {
			throw new ZWaveError(
				"Invalid event data length",
				ZWaveErrorCodes.Argument_Invalid,
			);
		}
		// ASCII data MUST be padded with 0xFF to fit 16 byte blocks
		if (this.dataType === EntryControlDataTypes.ASCII && data.length > 0) {
			const padded = new Bytes(Math.ceil(data.length / 16) * 16).fill(
				0xff,
			);
			padded.set(data);
			data = padded;
		}
		this.payload = Bytes.concat([
			[
				this.sequenceNumber,
				this.dataType & 0b11,
				this.eventType,
				data.length,
			],
			data,
		]);
		return super.serialize(ctx);
	}

	public toLogEntry(ctx?: GetValueDB): MessageOrCCLogEntry {
		const message: MessageRecord = {
			"sequence number": this.sequenceNumber,
			"data type": this.dataType,
			"event type": this.eventType,
		};
		if (this.eventData) {
			switch (this.eventType) {
				case EntryControlEventTypes.CachedKeys:
				case EntryControlEventTypes.Enter:
					// The event data is likely the user's PIN code, hide it from logs
					message["event data"] = "*".repeat(this.eventData.length);
					break;

				default:
					message["event data"] =
						typeof this.eventData === "string"
							? this.eventData
							: buffer2hex(this.eventData);

